// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number_,
        uint64 ts1,
        uint64 ts2,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_
    ) public {
        // timestamps must be valid uint64 values (they already are) and must differ
        // so that "latest call wins" is distinguishable from "first call sticks".
        vm.assume(ts1 != ts2);

        vm.startPrank(depositor);
        c.setL1BlockValues(number_, ts1, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        // sanity of the rule on the first call: timestamp must be ts1 for both versions
        c.setL1BlockValues(number_, ts2, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        vm.stopPrank();

        // General rule: after any sequence of successful setL1BlockValues calls,
        // c.timestamp() equals the _timestamp of the MOST RECENT successful call.
        assertTrue(c.timestamp() == ts2);
    }
}
